import {renderAlbum} from './albums.mjs';
export function mentionToken(text,caret=text.length){const prefix=text.slice(0,Math.max(0,Math.min(caret,text.length))),match=/(?:^|[\s(])(@[^\s@]*)$/u.exec(prefix);return match?{term:match[1].slice(1),start:prefix.length-match[1].length,end:prefix.length}:null;}
export function initMentions(c){
 const {$,state,table,req,button,element,busy,signedImage}=c;let chosen=new Map(),generation=0,timer,inlineGeneration=0,inlineTimer,activeIndex=0;
 const input=$('post-body'),popup=element('div',undefined,'mention-suggestions');popup.id='inline-mention-results';popup.hidden=true;popup.setAttribute('role','listbox');popup.setAttribute('aria-label','اقتراحات منشن، أقارب شجرتك أولًا');input.after(popup);input.setAttribute('aria-controls',popup.id);input.setAttribute('aria-autocomplete','list');
 const find=term=>req('/rest/v1/rpc/mention_search',{method:'POST',body:{term}});
 function paint(){const box=$('mention-selected');box.replaceChildren();for(const [id,name]of chosen)box.append(button('✕ '+name,()=>{chosen.delete(id);paint();},'secondary'));}
 function add(person){if(!chosen.has(person.id)&&chosen.size>=20)throw new Error('يمكن اختيار 20 عضوًا كحد أقصى.');chosen.set(person.id,person.display_name);paint();}
 function option(person,choose){const node=button('',choose,'mention-option');node.setAttribute('role','option');const avatar=element('span',person.display_name.slice(0,1),'avatar'),name=element('span',person.display_name);if(person.relation_label)name.append(element('small',person.relation_label));node.append(avatar,name);return node;}
 function hide(){popup.hidden=true;popup.replaceChildren();input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}
 function paintActive(){const rows=[...popup.querySelectorAll('[role=option]')];rows.forEach((row,index)=>row.setAttribute('aria-selected',String(index===activeIndex)));if(rows[activeIndex])input.setAttribute('aria-activedescendant',rows[activeIndex].id);}
 function suggest(){clearTimeout(inlineTimer);const version=++inlineGeneration,token=mentionToken(input.value,input.selectionStart);if(!token){hide();return;}
  inlineTimer=setTimeout(async()=>{try{const people=await find(token.term);if(version!==inlineGeneration||!$('editor').open)return;const current=mentionToken(input.value,input.selectionStart);if(!current||current.start!==token.start||current.term!==token.term)return;
   popup.replaceChildren(element('small','أقارب شجرتك أولًا، ثم بقية الأعضاء','mention-hint'));activeIndex=0;for(const [index,p]of people.entries()){
    const choose=()=>{const live=mentionToken(input.value,input.selectionStart);if(!live)return;add(p);const insertion='@'+p.display_name+' ';input.setRangeText(insertion,live.start,live.end,'end');hide();inlineGeneration++;input.focus();input.dispatchEvent(new Event('change',{bubbles:true}));};
    const row=option(p,choose);row.id='mention-option-'+index;row.onpointerdown=e=>e.preventDefault();popup.append(row);
   }if(!people.length)popup.append(element('p','لا توجد أسماء مطابقة.'));popup.hidden=false;input.setAttribute('aria-expanded','true');paintActive();
  }catch{if(version===inlineGeneration){popup.replaceChildren(element('p','تعذّر البحث. أعد المحاولة.'));popup.hidden=false;}}},180);
 }
 input.addEventListener('input',suggest);input.addEventListener('click',suggest);input.addEventListener('keyup',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key))suggest();});
 input.addEventListener('keydown',e=>{if(popup.hidden)return;const rows=popup.querySelectorAll('[role=option]');if(e.key==='Escape'){e.preventDefault();e.stopPropagation();inlineGeneration++;hide();}else if(rows.length&&['ArrowDown','ArrowUp','Enter'].includes(e.key)){e.preventDefault();if(e.key==='Enter')rows[activeIndex]?.click();else{activeIndex=(activeIndex+(e.key==='ArrowDown'?1:-1)+rows.length)%rows.length;paintActive();}}});
 $('editor').addEventListener('close',()=>{generation++;inlineGeneration++;clearTimeout(timer);clearTimeout(inlineTimer);hide();});
 $('mention-search').oninput=searchManual;$('mention-search').onfocus=searchManual;
 function searchManual(){clearTimeout(timer);const version=++generation;timer=setTimeout(async()=>{const term=$('mention-search').value.trim().replace(/^@/,'');$('mention-results').replaceChildren();try{const rows=await find(term);if(version!==generation)return;for(const p of rows.filter(p=>!chosen.has(p.id)))$('mention-results').append(option(p,()=>{add(p);$('mention-search').value='';$('mention-results').replaceChildren();}));if(!$('mention-results').children.length)$('mention-results').textContent='لا توجد نتائج أخرى.';}catch{if(version===generation)$('mention-results').textContent='تعذّر البحث. حاول مجددًا.';}},180);}
 function open(p){generation++;inlineGeneration++;clearTimeout(timer);clearTimeout(inlineTimer);hide();chosen=new Map((p?.mentioned_member_ids||[]).map(id=>[id,'عضو مذكور']));paint();$('mention-search').value='';$('mention-results').replaceChildren();const version=generation;if(chosen.size)table('profiles','select=id,display_name&id=in.('+[...chosen.keys()].join(',')+')').then(rows=>{if(version!==generation)return;for(const r of rows)if(chosen.has(r.id))chosen.set(r.id,r.display_name);paint();}).catch(()=>{});}
 async function mentioned(){const d=element('dialog');d.append(element('h2','أخبار مذكور فيها'),button('✕ إغلاق',()=>{d.close();d.remove();},'text-button'));document.body.append(d);d.showModal();let offset=0;const list=element('div'),more=button('عرض أخبار أقدم',load,'secondary');d.append(list,more);async function load(){const rows=await table('posts','select=id,title,body,image_path,image_paths,created_at,profiles:profiles!posts_author_id_fkey(display_name)&mentioned_member_ids=cs.'+encodeURIComponent('{'+state.user.id+'}')+'&published=eq.true&deleted_at=is.null&order=created_at.desc,id.desc&limit=20&offset='+offset);offset+=rows.length;more.hidden=rows.length<20;for(const p of rows){const card=element('article',undefined,'activity-row');card.append(element('small',(p.profiles?.display_name||'عضو')+' · '+new Date(p.created_at).toLocaleDateString('ar-SA')),element('h3',p.title),element('p',p.body,'body'));const album=await renderAlbum(p,signedImage);if(album)card.append(album);list.append(card);}if(!offset)list.append(element('p','لا توجد أخبار منشورة مذكور فيها اسمك بعد.','muted'));}await busy(more,load);}
 return {open,ids:()=>[...chosen.keys()],mount(){const b=button('@ أخبار مذكور فيها',mentioned,'secondary');b.id='mentioned-news-open';$('profile-dialog').append(b);}};
}
